<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {localFetch,readJson} from './http'
import Icon from './Icon.vue'
import {heatColor,monthStats,latestCompleteMonth,windowStatistics,windowMonthlyStats,electionYearOptions,electionYearsInWindow,sectorCaption,sectorTooltip,sectorRanking} from './monthlyStatistics'
import type {MonthReport,MonthClose,MonthYear,MonthExtreme,ElectionYearCategory,SectorMode} from './monthlyStatistics'
const props=defineProps<{initial?:MonthReport}>()
const data=ref<MonthReport|null>(props.initial||null),error=ref(''),loading=ref(!props.initial),updating=ref(false),compare=ref(false),period=ref('all')
const sectorMode=ref<SectorMode>('monthly')
const sectorRange=computed(()=>sectorMode.value==='ytd'?{first:data.value?.sector_metadata?.ytd_first_month,last:data.value?.sector_metadata?.ytd_last_month}:{first:data.value?.sector_metadata?.first_month,last:data.value?.sector_metadata?.last_month})
function changeSectorMode(mode:SectorMode){sectorMode.value=mode;try{localStorage.setItem('monthly-sector-ranking-mode',mode)}catch{}}
onMounted(()=>{try{if(localStorage.getItem('monthly-sector-ranking-mode')==='ytd')sectorMode.value='ytd'}catch{}})
let timer:number|undefined
const tw=computed(()=>data.value?.markets.taiex),sp=computed(()=>data.value?.markets.sp500)
const latestYear=computed(()=>Number(tw.value?.latest_month.slice(0,4)||new Date().getFullYear()))
const startYear=computed(()=>period.value==='10'?latestYear.value-9:period.value==='20'?latestYear.value-19:0)
const years=computed(()=>tw.value?.years.filter(y=>y.year>=startYear.value)||[])
const stats=computed(()=>[{key:'taiex',label:'台股加權指數',values:monthStats(tw.value?.rows||[],startYear.value)},...(compare.value?[{key:'sp500',label:'S&P 500 · 相同台股月份',values:monthStats(sp.value?.rows||[],startYear.value)}]:[])])
const completeRows=computed(()=>tw.value?.rows.filter(r=>r.return_pct!=null&&!r.partial&&Number(r.month.slice(0,4))>=startYear.value)||[])
const latest=computed(()=>tw.value?.rows.at(-1))
const windowPeriod=ref('2'),electionCategory=ref<ElectionYearCategory>('all')
const selectedElection=computed(()=>electionYearOptions.find(o=>o.key===electionCategory.value)!)
const windowEnd=computed(()=>latestCompleteMonth(tw.value?.rows||[]))
const windowMarkets=computed(()=>[{key:'taiex',label:'台股加權指數',rows:tw.value?.rows||[]},...(compare.value?[{key:'sp500',label:'S&P 500 · 相同台股月份',rows:sp.value?.rows||[]}]:[])].map(m=>({...m,windows:windowStatistics(m.rows,windowEnd.value)})))
const windowDetails=computed(()=>windowMarkets.value.map(m=>{const w=m.windows.find(w=>w.key===windowPeriod.value)!;return {key:m.key,label:m.label,window:w,months:windowMonthlyStats(m.rows,w,electionCategory.value),includedYears:electionYearsInWindow(m.rows,w,electionCategory.value)}}))
const currentRun=computed(()=>windowMarkets.value[0]?.windows.find(w=>w.key==='all')?.current)
const frequency=(n:number|null|undefined)=>n==null?'—':fmt(n)+'%'
const extremeDates=(e:MonthExtreme|null|undefined)=>e?.months.join('、')||''
const extremeDateLabel=(e:MonthExtreme|null|undefined)=>e?.months.length?e.months[0]+(e.months.length>1?'等'+e.months.length+'次':''):''

const sourceErrors=computed(()=>Object.entries(data.value?.source_errors||{}).filter(([k])=>k==='taiex'||k==='sectors'||compare.value).map(([k,v])=>`${k==='taiex'?'台股':k==='sectors'?'自訂族群':'S&P 500'}：${v}`))
const fmt=(v:number|null|undefined,d=1)=>v==null?'—':v.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d})
const percent=(v:number|null|undefined)=>v==null?'—':`${v>0?'+':''}${fmt(v)}%`
const spyYear=(year:number)=>sp.value?.years.find(y=>y.year===year)
const tooltip=(r:MonthClose|null|undefined)=>!r?'尚無月份資料':r.return_pct==null?`${r.month}只有基準收盤，缺前月底收盤，不能計算報酬`:`${r.previous_date} ${fmt(r.previous_close,2)} → ${r.date} ${fmt(r.close,2)}；${r.partial?(r.in_progress?'本月迄今':'月份資料未完整'):'已結束月份'}`
const annualTip=(y:MonthYear|undefined)=>!y||y.return_pct==null?'缺前一年底收盤或完整月份，無法計算年度漲跌':`相對前一年最後收盤，計至${y.through}；以指數比值計算，不是月漲跌加總`
async function load(){
 try{const r=await localFetch('/api/monthly-statistics');const value=await readJson(r);if(!r.ok||value.error)throw new Error(value.error||'無法讀取月份統計');data.value=value;error.value='';updating.value=value.job.status==='running';if(updating.value)timer=window.setTimeout(load,1500)}catch(e){error.value=(e as Error).message;updating.value=false}finally{loading.value=false}
}
async function refresh(){if(updating.value)return;updating.value=true;error.value='';try{const r=await localFetch('/api/monthly-statistics/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const value=await readJson(r);if(!r.ok)throw new Error(value.error||'更新失敗');timer=window.setTimeout(load,700)}catch(e){error.value=(e as Error).message;updating.value=false}}
onMounted(load);onUnmounted(()=>window.clearTimeout(timer))
</script>
<template>
 <section class="monthly-statistics">
  <header class="page-heading"><div><span class="eyebrow">MONTHLY MARKET STATISTICS</span><h1>月份漲跌統計</h1><p>以台股可追溯月份為主，從月末收盤觀察每年與各月份的漲跌。</p></div><button class="refresh-button" :disabled="updating" @click="refresh"><Icon name="refresh" :size="16"/>{{updating?'更新中':'更新月份資料'}}</button></header>
  <p v-if="error" class="notice error" role="alert">{{error}}；已有資料會保留顯示。</p>
  <p v-if="sourceErrors.length" class="notice error">部分來源未更新，保留原收盤日期：{{sourceErrors.join('；')}}</p>
  <p v-if="data?.job.status==='failed'" class="notice error">{{data.job.message}}</p>
  <p v-if="loading" class="notice">正在讀取月份統計…</p>
  <template v-if="tw">
   <div class="overview"><article><small>台股可計算月漲跌</small><strong>{{tw.first_return_month}}<em>起</em></strong><span>1967年1月收盤只作起算基準</span></article><article><small>最新收盤 · {{latest?.partial?(latest?.in_progress?'本月迄今':'月份資料未完整'):'已結束月份'}}</small><strong>{{tw.as_of}}</strong><span>{{fmt(tw.latest_close,2)}}點 · {{percent(latest?.return_pct)}}</span></article><article><small>目前範圍完整月份</small><strong>{{completeRows.length}}<em>個月</em></strong><span>曆月統計不計本月迄今</span></article></div>
   <div class="controls"><label>期間<select v-model="period" aria-label="月份統計期間"><option value="all">全部歷史</option><option value="20">近20年</option><option value="10">近10年</option></select></label><label class="comparison-toggle"><input type="checkbox" v-model="compare"/>對照 S&P 500（同台股月份）</label><span class="saved">{{data?.saved_at?'資料更新 '+data.saved_at.slice(0,16).replace('T',' '):'歷史資料已載入'}}</span></div>
   <p v-if="compare" class="comparison-note">台股截至{{tw.as_of}}；S&P 500截至{{sp?.as_of||'尚無資料'}}。各取當地收盤，以同一曆月比對，不換算匯率。</p>
   <article class="panel"><div class="panel-heading"><div><h2>歷年月份漲跌</h2><p>紅色上漲、綠色下跌，顏色越深代表幅度越大。＊為本月迄今、資料未完整或未結束年度。</p></div><span>價格漲跌幅 %</span></div>
    <div class="sector-controls" role="group" aria-label="族群排名方式"><span>族群前三名</span><button type="button" :aria-pressed="sectorMode==='monthly'" @click="changeSectorMode('monthly')">當月漲幅</button><button type="button" :aria-pressed="sectorMode==='ytd'" @click="changeSectorMode('ytd')">年初至今（YTD）</button></div>
    <p class="sector-mode-note">{{sectorMode==='ytd'?'族群按前一年底至各月底的累積漲幅排名。':'族群按前月底至各月底的單月漲幅排名。'}}切換僅改變族群排名，格內百分比仍為台股當月漲跌。</p>
    <p class="scroll-hint">表格可左右滑動；移到數值可看起訖收盤。</p>
    <div class="matrix-scroll" tabindex="0" aria-label="歷年月份漲跌，可左右捲動"><table class="year-matrix"><thead><tr><th class="year-column">年度／市場</th><th v-for="m in 12" :key="m">{{m}}月</th><th>全年／年初至今</th></tr></thead><tbody v-for="y in years" :key="y.year"><tr class="taiex-row"><th class="year-column"><b>{{y.year}}</b><small>台股</small></th><td v-for="(r,i) in y.months" :key="i" :style="heatColor(r?.return_pct)" :title="tooltip(r)" :data-month="`${y.year}-${String(i+1).padStart(2,'0')}`">{{percent(r?.return_pct)}}<sup v-if="r?.partial">＊</sup><small v-if="r&&r.return_pct!=null" class="sector-leaders" :class="{unavailable:!sectorRanking(r,sectorMode).leaders.length}" :title="sectorTooltip(r,sectorMode)" :data-sector-month="r.month">{{sectorCaption(r,sectorMode)}}</small></td><td class="annual" :style="heatColor(y.return_pct)" :title="annualTip(y)">{{percent(y.return_pct)}}<sup v-if="y.partial&&y.return_pct!=null">＊</sup></td></tr>
     <tr v-if="compare" class="sp-row"><th class="year-column"><span>{{y.year}}</span><small>S&P 500</small></th><td v-for="m in 12" :key="m" :style="heatColor(spyYear(y.year)?.months[m-1]?.return_pct)" :title="tooltip(spyYear(y.year)?.months[m-1])">{{percent(spyYear(y.year)?.months[m-1]?.return_pct)}}<sup v-if="spyYear(y.year)?.months[m-1]?.partial">＊</sup></td><td class="annual" :style="heatColor(spyYear(y.year)?.return_pct)" :title="annualTip(spyYear(y.year))">{{percent(spyYear(y.year)?.return_pct)}}<sup v-if="spyYear(y.year)?.partial&&spyYear(y.year)?.return_pct!=null">＊</sup></td></tr>
    </tbody></table></div>
    <p class="sector-note">括號為我們自訂族群的{{sectorMode==='ytd'?'年初至今（YTD）':'當月'}}漲幅前三名，依成員{{sectorMode==='ytd'?'從前一年底到該月底的價格報酬':'月報酬'}}等權平均排序；滑到名稱可看漲幅及涵蓋檔數。至少2檔且成員行情涵蓋達80%才列入，僅列上漲族群。<template v-if="sectorRange.first">可計算範圍{{sectorRange.first}}～{{sectorRange.last}}。</template>依目前分類回看，非當年分類與成員；含存活者偏差。族群可重疊，不是對大盤的貢獻排名。＊月份為截至該格日期的暫排行。</p>
    <div class="legend"><span v-for="(v,i) in [-12,-7,-2,2,7,15,25,35]" :key="v" :style="heatColor(v)">{{['≤−10%','−10～−5%','−5～0%','0～5%','5～10%','10～20%','20～30%','≥30%'][i]}}</span></div>
   </article>
   <article class="panel seasonal-panel"><div class="panel-heading"><div><h2>曆月統計</h2><p>只計目前期間已結束的月份；不含本月迄今，也不把缺值當作0%。</p></div></div>
    <div class="matrix-scroll" tabindex="0" aria-label="各月份歷史漲跌統計，可左右捲動"><table class="seasonal-table"><thead><tr><th class="year-column">指標</th><th v-for="m in 12" :key="m">{{m}}月</th></tr></thead><tbody v-for="s in stats" :key="s.key"><tr class="market-label"><th colspan="13">{{s.label}}</th></tr><tr><th class="year-column">上漲比例</th><td v-for="(v,i) in s.values" :key="i">{{v.up_rate==null?'—':fmt(v.up_rate)+'%'}}</td></tr><tr><th class="year-column">平均漲跌</th><td v-for="(v,i) in s.values" :key="i" :style="heatColor(v.mean)">{{percent(v.mean)}}</td></tr><tr><th class="year-column">中位數漲跌</th><td v-for="(v,i) in s.values" :key="i" :style="heatColor(v.median)">{{percent(v.median)}}</td></tr><tr class="sample-counts"><th class="year-column">上漲／下跌／持平<small>樣本數</small></th><td v-for="(v,i) in s.values" :key="i">{{v.up}}／{{v.down}}／{{v.flat}}<small>{{v.n}}個月</small></td></tr></tbody></table></div>
    <p class="method-note">上漲比例＝歷史上漲月份數÷完整月份數；平均、中位數都是單月報酬，不是未來上漲機率。不同年代的市場條件也不同。</p>
   </article>
   <article class="panel lookback-panel" aria-label="不同年期月漲跌與連續月份統計">
    <div class="panel-heading"><div><h2>不同年期的漲跌機率與幅度</h2><p>機率以歷史完整月份的出現比例表示；近2／5／10／20年採連續24／60／120／240個曆月，各年期均截至{{windowEnd||'尚無完整月份'}}。</p></div><span>完整月份統計</span></div>
    <p v-if="currentRun?.direction!=='none'&&currentRun" class="current-run" :class="currentRun.direction"><b>截至{{windowEnd}}</b> · {{currentRun.direction==='up'?'目前連漲':currentRun.direction==='down'?'目前連跌':'當月持平'}}<span v-if="currentRun.direction!=='flat'">{{currentRun.length}}個月</span><small v-if="currentRun.direction!=='flat'">{{currentRun.start}}～{{currentRun.end}}</small></p>
    <p class="scroll-hint">此區獨立比較五個年期；左右滑動可看單月極值與最長連漲／連跌。</p>
    <div class="matrix-scroll lookback-scroll" tabindex="0" aria-label="2年5年10年20年全部歷史比較，可左右捲動"><table class="lookback-table"><thead><tr><th class="year-column">期間</th><th>完整月份</th><th>平均月漲跌</th><th>上漲比例</th><th>下跌比例</th><th>持平比例</th><th>最大單月漲幅</th><th>最低單月漲幅</th><th>最長連漲</th><th>最長連跌</th></tr></thead><tbody v-for="market in windowMarkets" :key="market.key"><tr class="market-label"><th colspan="10">{{market.label}}</th></tr><tr v-for="w in market.windows" :key="w.key" :data-lookback="market.key+'-'+w.key"><th class="year-column">{{w.label}}<small>{{w.from||'—'}}<br/>～{{w.through||'—'}}</small></th><td>{{w.n}}<small>範圍{{w.expected_months}}個月<span v-if="w.n<w.expected_months"> · 樣本不足</span></small></td><td :style="heatColor(w.mean)">{{percent(w.mean)}}</td><td>{{frequency(w.up_rate)}}<small>{{w.up}}次</small></td><td>{{frequency(w.down_rate)}}<small>{{w.down}}次</small></td><td>{{frequency(w.flat_rate)}}<small>{{w.flat}}次</small></td><td :style="heatColor(w.maximum?.value)" :title="extremeDates(w.maximum)">{{percent(w.maximum?.value)}}<small>{{extremeDateLabel(w.maximum)}}</small></td><td :style="heatColor(w.minimum?.value)" :title="extremeDates(w.minimum)">{{percent(w.minimum?.value)}}<small>{{extremeDateLabel(w.minimum)}}</small></td><td>{{w.n?w.longest_up.length+'個月':'—'}}<small v-if="w.longest_up.length">{{w.longest_up.start}}<br/>～{{w.longest_up.end}}</small></td><td>{{w.n?w.longest_down.length+'個月':'—'}}<small v-if="w.longest_down.length">{{w.longest_down.start}}<br/>～{{w.longest_down.end}}</small></td></tr></tbody></table></div>
    <p class="method-note">上漲／下跌／持平比例的分母都是該年期完整月份數。連漲、連跌以相鄰曆月計算；持平、缺值、月份間斷會中止連續紀錄，期間起點以前不延伸計數。同長度的最長紀錄顯示最早一段。極值為單月報酬，最小值可為負數。</p>
    <div class="window-detail-heading"><h3>選年期查看1～12月</h3><div class="window-buttons" role="group" aria-label="逐月機率比較年期"><button v-for="w in windowMarkets[0]?.windows" :key="w.key" :class="{active:windowPeriod===w.key}" :aria-pressed="windowPeriod===w.key" @click="windowPeriod=w.key">{{w.label}}</button></div></div>
    <div class="election-controls"><span>年份類型</span><div class="window-buttons" role="group" aria-label="選舉年份篩選"><button v-for="option in electionYearOptions" :key="option.key" :class="{active:electionCategory===option.key}" :aria-pressed="electionCategory===option.key" @click="electionCategory=option.key">{{option.label}}</button></div></div>
    <p class="election-note">{{selectedElection.note}}<a v-if="selectedElection.url" :href="selectedElection.url" target="_blank" rel="noopener noreferrer">{{selectedElection.source}} ↗</a><br/>篩選適用於下方逐月表，與所選年期取交集；選舉年可能只納入範圍內的部分月份。</p>
    <div v-if="electionCategory!=='all'" class="election-years" aria-live="polite"><p v-for="market in windowDetails" :key="market.key"><b>{{market.label}}實際年份：</b><template v-if="market.includedYears.length"><span v-for="(y,i) in market.includedYears" :key="y.year">{{i?'、':''}}{{y.year}}（{{y.n}}個月）</span></template><span v-else>此年期沒有符合的完整月份，可改選較長年期。</span></p></div>
    <p class="comparison-note">下表將同一曆月分開統計，例如近2年的每個月份最多只有2筆。各月份的比例與幅度都來自所選年期，不是未來預測。</p>
    <div class="matrix-scroll" tabindex="0" aria-label="所選年期各月份漲跌比例與極值，可左右捲動"><table class="month-window-table"><thead><tr><th class="year-column">月份</th><th>樣本數</th><th>平均漲跌</th><th>上漲比例</th><th>下跌比例</th><th>持平比例</th><th>最大單月漲幅</th><th>最低單月漲幅</th></tr></thead><tbody v-for="market in windowDetails" :key="market.key"><tr class="market-label"><th colspan="8">{{market.label}} · {{market.window.label}} · {{selectedElection.label}} · {{market.window.from||'—'}}～{{market.window.through||'—'}}</th></tr><tr v-for="m in market.months" :key="m.month" :data-window-month="market.key+'-'+m.month"><th class="year-column">{{m.month}}月</th><td>{{m.n}}筆</td><td :style="heatColor(m.mean)">{{percent(m.mean)}}</td><td>{{frequency(m.up_rate)}}<small>{{m.up}}次</small></td><td>{{frequency(m.down_rate)}}<small>{{m.down}}次</small></td><td>{{frequency(m.flat_rate)}}<small>{{m.flat}}次</small></td><td :style="heatColor(m.maximum?.value)" :title="extremeDates(m.maximum)">{{percent(m.maximum?.value)}}<small>{{extremeDateLabel(m.maximum)}}</small></td><td :style="heatColor(m.minimum?.value)" :title="extremeDates(m.minimum)">{{percent(m.minimum?.value)}}<small>{{extremeDateLabel(m.minimum)}}</small></td></tr></tbody></table></div>
   </article>
   <details class="sources"><summary>計算方式與資料來源</summary><p>{{data?.note}}</p><p>{{data?.history_note}}</p><p>全年報酬＝年底收盤÷前一年底收盤−1；當年度改用最新完整收盤。不是各月漲跌幅直接加總。沒有前一年底收盤或月份缺漏時留空。</p><p v-if="tw.missing_months.length">台股缺少月份：{{tw.missing_months.join('、')}}</p><div v-for="market in [tw,...(compare&&sp?[sp]:[])]" :key="market.metadata.label"><h3>{{market.metadata.label}}</h3><p v-for="s in market.metadata.sources" :key="s.id"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.label}} ↗</a><span v-if="s.retrieved_at"> · 取得{{s.retrieved_at.slice(0,10)}}</span><small>{{s.note}}</small></p><p v-if="market.metadata.archive_check">轉載與官方重疊{{market.metadata.archive_check.overlap_days.toLocaleString()}}個交易日逐筆比對，差異{{market.metadata.archive_check.mismatches}}筆；更早區段仍屬轉載資料。</p></div></details>
  </template>
 </section>
</template>
